package engine;
import java.util.*;
import java.nio.file.*;
import java.io.*;
public final class Json {
 public static Object read(Path p)throws IOException{return parse(Files.readString(p));}
 public static void write(Path p,Object x)throws IOException{Files.createDirectories(p.toAbsolutePath().getParent());Path t=Files.createTempFile(p.toAbsolutePath().getParent(),"write-",".tmp");Files.writeString(t,stringify(x));try{Files.move(t,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(t,p,StandardCopyOption.REPLACE_EXISTING);}}
 public static String stringify(Object v){if(v==null)return "null";if(v instanceof String s){StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray())switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof Map<?,?> m){List<String>a=new ArrayList<>();m.forEach((k,x)->a.add(stringify(k.toString())+":"+stringify(x)));return "{"+String.join(",",a)+"}";}if(v instanceof Iterable<?> it){List<String>a=new ArrayList<>();it.forEach(x->a.add(stringify(x)));return "["+String.join(",",a)+"]";}throw new IllegalArgumentException("不支持JSON值 "+v.getClass());}
 public static Object parse(String s){P p=new P(s);Object v=p.v();p.ws();if(p.i!=s.length())throw new IllegalArgumentException("JSON尾部非法 "+p.i);return v;}
 @SuppressWarnings("unchecked") public static Map<String,Object> map(Object o){return (Map<String,Object>)o;}
 @SuppressWarnings("unchecked") public static List<Object> list(Object o){return (List<Object>)o;}
 static class P{final String s;int i;P(String s){this.s=s;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}Object v(){ws();if(i>=s.length())throw new IllegalArgumentException("JSON意外结束");char c=s.charAt(i);if(c=='"')return str();if(c=='['){i++;List<Object>a=new ArrayList<>();ws();if(s.charAt(i)==']'){i++;return a;}do{a.add(v());ws();c=s.charAt(i++);if(c==']')return a;if(c!=',')throw new IllegalArgumentException("JSON数组");}while(true);}if(c=='{'){i++;Map<String,Object>m=new LinkedHashMap<>();ws();if(s.charAt(i)=='}'){i++;return m;}do{ws();String k=str();ws();if(s.charAt(i++)!=':')throw new IllegalArgumentException("JSON对象");m.put(k,v());ws();c=s.charAt(i++);if(c=='}')return m;if(c!=',')throw new IllegalArgumentException("JSON对象");}while(true);}for(String x:List.of("true","false","null")){if(s.startsWith(x,i)){i+=x.length();return x.equals("null")?null:Boolean.valueOf(x);}}int a=i;if(c=='-')i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;if(i<s.length()&&s.charAt(i)=='.'){i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;}if(i<s.length()&&"eE".indexOf(s.charAt(i))>=0){i++;if(i<s.length()&&"+-".indexOf(s.charAt(i))>=0)i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;}String n=s.substring(a,i);if(n.contains(".")||n.contains("e")||n.contains("E"))return Double.valueOf(n);return Long.valueOf(n);}String str(){if(s.charAt(i++)!='"')throw new IllegalArgumentException("JSON字符串");StringBuilder b=new StringBuilder();while(i<s.length()){char c=s.charAt(i++);if(c=='"')return b.toString();if(c=='\\'){char e=s.charAt(i++);switch(e){case '"','\\','/'->b.append(e);case 'n'->b.append('\n');case 'r'->b.append('\r');case 't'->b.append('\t');case 'b'->b.append('\b');case 'f'->b.append('\f');case 'u'->{b.append((char)Integer.parseInt(s.substring(i,i+4),16));i+=4;}default->throw new IllegalArgumentException("JSON转义");}}else b.append(c);}throw new IllegalArgumentException("JSON字符串未结束");}}
}
